function quoteTotalsOf(r){const subtotal=(r.lines||[]).reduce((sum,l)=>sum+Math.round(Number(l.unit_price||0)*100)*Number(l.quantity||0),0);const discount=Math.round(subtotal*Number(r.discount_percent||0)/100);const net=subtotal-discount;const tax=Math.round(net*Number(r.tax_percent||0)/100);return {subtotal:subtotal/100,discount:discount/100,net:net/100,tax:tax/100,total:(net+tax)/100};}
