 if(f.type==='lines'){if(!v.length)add(f.key,'Add at least one line item.');else if(v.some(l=>!String(l.description||'').trim()||!Number.isInteger(Number(l.quantity))||Number(l.quantity)<1||!Number.isFinite(Number(l.unit_price))||Number(l.unit_price)<0||Math.abs(Number(l.unit_price)*100-Math.round(Number(l.unit_price)*100))>1e-6||!['Recurring monthly','Recurring annual','One-time'].includes(l.billing)))add(f.key,'Each line needs a description, positive whole quantity, and valid nonnegative price.');else if(v.some(l=>l.product_id&&recordById(l.product_id)?.currency!==values.currency))add(f.key,'Quote currency must match each linked catalog product.');}
