function createLinkedCompany(values,persist){if(!values.company_name)return values.account_id||'';if(values.account_id)return values.account_id;let account=recordsOf('account').find(r=>r.company_name?.trim().toLowerCase()===values.company_name.trim().toLowerCase());if(!account){account={...formDefaults('account'),...Object.fromEntries(['company_name','industry','website','country','city','address','company_size','annual_revenue','owner'].map(k=>[k,values[k]||''])),id:'account_'+crypto.randomUUID(),type:'account',relationship:'Prospect',territory:values.country||'India',currency:values.currency||'INR',version:1,_persist:persist,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};LOCAL_DB.records.account.push(account);}return account.id;}
