const recordRoute=r=>FORMS[r.type].detail+'?record='+encodeURIComponent(r.id);
function projectTableRow(r,c){if(r._seedRow)return r._seedRow;const meta=r.company_name||relationName(r.account_id)||relationName(r.customer_id)||r.email||r.offer||r.sku||r.territory||r.type;return c.columns.map((col,i)=>{if(i===0)return recordName(r)+'|'+meta;const k=col.toLowerCase();if(/owner|manager/.test(k))return r.owner||r.manager||'Unassigned';if(/email|contact/.test(k))return r.email||relationName(r.contact_id)||r.phone||'Not provided';if(/industry/.test(k))return r.industry||(r.industries||[]).join(', ')||'Not provided';if(/channel/.test(k))return r.channel||(r.channels||[]).join(', ')||'Not selected';if(/company|account|customer/.test(k))return r.company_name||relationName(r.account_id||r.customer_id)||'Not linked';if(/territory|scope/.test(k))return r.territory||(Array.isArray(r.scope)?r.scope.join(', '):r.scope)||'Not provided';if(/role/.test(k))return r.role||r.job_title||r.buying_role||'Not provided';if(/next|action|milestone/.test(k))return r.next_step||r.next_milestone||r.success_measure||'Review details';if(/due|date|renewal/.test(k))return r.due||r.due_date||r.renewal_date||r.expected_close||r.start||r.end_date||'Not set';if(/budget|amount|value|revenue|arr/.test(k))return moneyValue(r.total_budget??r.amount??r.annual_recurring??r.current_arr??r.value??0,r.currency);if(/eligibility|permission/.test(k))return r.email_scope||r.permission||'Not verified';if(/status|state|health|risk|preparation|acceptance|handoff|readiness/.test(k))return r.status||r.qualification||r.lifecycle||r.relationship||'Draft';if(/offer/.test(k))return r.offer||'Not provided';if(/version/.test(k))return r.version||'v1';if(/member/.test(k))return (r.members||[]).length+' members';if(/evidence|source/.test(k))return r.evidence||r.evidence_required||r.source||r.source_url||'Review source';if(/segment|audience/.test(k))return r.personas||relationName(r.icp_id)||r.audience||'Review details';if(/fit|score/.test(k))return r.fit_threshold||'Needs assessment';if(/trigger|event/.test(k))return r.trigger||r.event||'Not selected';return r[col.toLowerCase().replaceAll(' ','_')]||'Not provided';});}
function renderRecordDetail(r){const schema=FORMS[r.type];const sections=schema.sections.map(s=>panel(s.title,`<dl class="record-detail-grid">${s.fields.map(f=>{const v=r[f.key];if(f.type==='lines')return `<div class="record-detail-full"><dt>${h(f.label)}</dt><dd><div class="table-wrap"><table><thead><tr><th>Description</th><th>Quantity</th><th>Unit price</th><th>Billing</th></tr></thead><tbody>${(v||[]).map(l=>`<tr><td>${h(l.description)}</td><td>${h(l.quantity)}</td><td>${moneyValue(l.unit_price,r.currency)}</td><td>${h(l.billing)}</td></tr>`).join('')}</tbody></table></div>${renderQuoteTotals(r)}</dd></div>`;if(f.type==='steps')return `<div class="record-detail-full"><dt>${h(f.label)}</dt><dd>${(v||[]).map((v,i)=>`<div class="repeat-row"><h3>${i+1}. ${h(v.name)}</h3><p>${h(v.body)}</p><div class="small muted">${h(v.type)} · ${h(v.owner)} · ${h(v.wait_days)} business days</div></div>`).join('')||'No steps'}</dd></div>`;let text=f.type==='file'?(v?.name||'No file reference'):fieldDisplay(f,v);let value=h(text);if(f.type==='relation'&&recordById(v))value=`<a href="#/${recordRoute(recordById(v))}">${h(text)}</a>`;if(f.type==='email'&&v)value=`<a href="mailto:${h(v)}">${h(v)}</a>`;if(f.type==='url'&&v&&/^https?:\/\//.test(v))value=`<a href="${h(v)}" target="_blank" rel="noopener noreferrer">${h(v)}</a>`;return `<div class="${['textarea','multiselect'].includes(f.type)?'record-detail-full':''}"><dt>${h(f.label)}</dt><dd>${value}</dd></div>`;}).join('')}</dl>`)).join('');return `<div class="record-summary"><div><div class="eyebrow">${h(schema.label)} · ${r._fixture?'illustrative example':r._persist?'saved on this browser':'review session'}</div><h2>${h(recordName(r))}</h2><p class="small muted">${h(r.id)} · revision ${h(r._revision||1)} · updated ${h(new Date(r.updatedAt).toLocaleString())}</p></div><div class="flex">${go('Back to '+SCREEN[schema.screen].title,schema.screen)}${btn('Edit all details','edit-record:'+r.id,true)}${btn('Export record','export-record:'+r.id)}</div></div>${recordHandoffButtons(r)}<div class="record-sections">${sections}</div>${r.type==='quote'?notice('Authorization: '+h(r.authorization||'Pending')+' · Delivery: '+h(r.delivery||'Not sent')+'. Editing this quote creates a revision and resets its authorization.'):''}${r.type==='lead'&&r.contact_id?panel('Linked identity',`<div class="panel-body flex">${go('Open contact',recordRoute(recordById(r.contact_id)))}${r.account_id?go('Open company',recordRoute(recordById(r.account_id))):''}</div>`):''}`;}
function recordHandoffButtons(r){const types={lead:['task','meeting','opportunity'],account:['contact','opportunity'],contact:['lead','meeting'],campaign:['asset','post','capture'],opportunity:['task','proposal','quote'],quote:['contract'],contract:['customer'],customer:['onboarding','review','recovery','renewal','expansion','advocacy'],renewal:['review'],sequence:[],playbook:[]}[r.type]||[];return types.length?`<div class="toolbar record-handoffs"><span class="small muted">Create linked work</span>${types.map(t=>btn(FORMS[t].label,'linked-create:'+r.id+':'+t)).join('')}</div>`:'';}
function linkedDefaults(r,type){const v={owner:r.owner||'Maya Kapoor'};for(const f of fieldsOf(type)){if(f.type==='relation'){if(f.entity===r.type)v[f.key]=r.id;else if(r[f.key])v[f.key]=r[f.key];}if(['company_name','industry','country','currency','offer'].includes(f.key)&&r[f.key])v[f.key]=r[f.key];}if(r.type==='account')v.company_name=r.company_name;if(r.type==='lead'&&type==='contact')for(const f of PERSON_FIELDS)v[f.key]=r[f.key];if(r.type==='contact'&&type==='lead')for(const f of PERSON_FIELDS)v[f.key]=r[f.key];if(type==='quote')v.name=recordName(r)+' · quote';if(type==='contract'&&r.type==='quote'){v.name=recordName(r)+' · contract';v.currency=r.currency;v.one_time=(r.lines||[]).filter(l=>l.billing==='One-time').reduce((s,l)=>s+l.quantity*l.unit_price,0);v.annual_recurring=(r.lines||[]).filter(l=>l.billing!=='One-time').reduce((s,l)=>s+l.quantity*l.unit_price*(l.billing==='Recurring monthly'?12:1),0);}return v;}
function manualWorkspacePanel(screen){let types=Object.keys(FORMS).filter(t=>FORMS[t].screen===screen&&!ENTITY_SCREEN[screen]);if(screen==='calendar')types=['post'];if(screen==='home'){const records=Object.values(LOCAL_DB.records).flat().filter(r=>!r._fixture);return panel('Your added records',`<div class="panel-body"><div class="between"><span class="muted">${records.length} added records across this review workspace</span>${btn('Export added records','export-records')}</div><div class="manual-record-grid">${records.slice(-8).reverse().map(r=>`<a class="setting-card" href="#/${recordRoute(r)}"><div><h3>${h(recordName(r))}</h3><p>${h(FORMS[r.type].label)} · ${h(r.owner||r.manager||'Unassigned')}</p></div></a>`).join('')||'<p class="small muted">Add a campaign, lead, opportunity, or customer to work with complete records.</p>'}</div></div>`);}if(!types.length)return '';return `<div class="section-gap">${types.map(type=>{const rs=recordsOf(type);return panel(FORMS[type].label+' records',`<div class="manual-record-grid panel-body">${rs.map(r=>`<a class="setting-card" href="#/${recordRoute(r)}"><div><h3>${h(recordName(r))}</h3><p>${h(r._fixture?'Illustrative example':r.status||'Draft')} · ${h(r.owner||'Unassigned')}${type==='post'&&r.schedule?' · '+h(r.schedule+' '+r.timezone):''}</p></div></a>`).join('')||'<p class="small muted">No added records yet.</p>'}</div>`,btn('Add '+FORMS[type].label.toLowerCase(),'entity-create:'+type));}).join('')}</div>`;}
