function readPageSettings(){const selectors=[...document.querySelectorAll('#app .field input,#app .field select,#app .field textarea,#app .switch input')];return selectors.map((el,i)=>({key:el.getAttribute('aria-label')||el.closest('.field')?.childNodes[0]?.textContent?.trim()||'field-'+i,type:el.type||el.tagName.toLowerCase(),value:el.type==='checkbox'?el.checked:el.value}));}
function savePageSettings(key){const data=readPageSettings();LOCAL_DB.settings[key]=data;const ok=persistRecordWorkspace();toast(ok?'Preferences saved on this browser. Live enforcement requires the company backend.':'Preferences saved for this session; browser storage is unavailable.');}
function restorePageSettings(){restoreInlineRecord();const data=LOCAL_DB.settings[current==='setup'?'setup-'+state.setupStep:current];if(!Array.isArray(data))return;for(const f of inlineFields()){const saved=data.find(v=>v.key===f.label);if(saved){if(f.element.type==='checkbox')f.element.checked=saved.value;else f.element.value=saved.value;}}document.querySelectorAll('#app .switch input').forEach(el=>{const saved=data.find(v=>v.key===el.getAttribute('aria-label'));if(saved)el.checked=saved.value;});}
function captureLead(form){const data=Object.fromEntries(new FormData(form));const parts=(data.full_name||'').trim().split(/\s+/);const v={...formDefaults('lead'),first_name:parts.shift()||'',last_name:parts.join(' '),company_name:data.company_name,job_title:data.job_title,email:data.email,need:data.need,industry:'Other',country:'India',source:'Website request',offer:'Enterprise AI discovery',qualification:'Needs assessment',owner:'Maya Kapoor',next_step:'Qualify discovery request',email_scope:'Requested offer follow-up',eligibility_source:'Discovery request contact checkbox',email_scope_date:new Date().toISOString().slice(0,10)};if(!data.consent){toast('Contact permission is required for this request.');return;}openEntityForm('lead',{defaults:v});toast('Review the captured details and confirm where to keep this record.');}

let pendingImport=null;
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;const source=text.replace(/^\uFEFF/,'');for(let i=0;i<source.length;i++){const c=source[i];if(c==='"'){if(quoted&&source[i+1]==='"'){cell+='"';i++;}else if(quoted)quoted=false;else if(cell==='')quoted=true;else throw Error('Unexpected quote in row '+(rows.length+1));}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&source[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('An opening quote has no matching closing quote.');if(cell||row.length){row.push(cell);if(row.some(v=>v.trim()))rows.push(row);}return rows;}
async function validateCsvImport(){pendingImport=null;let result=document.getElementById('import-result');const file=document.getElementById('csv-file')?.files?.[0];if(!file){toast('Select a CSV file first.');return;}if(file.size>2*1024*1024){toast('Use a CSV file smaller than 2 MB.');return;}try{const text=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Unable to read this file.'));reader.readAsText(file);});const rows=parseCsv(text);if(rows.length<2)throw Error('Include a header and at least one data row.');if(rows.length>1001)throw Error('Import up to 1,000 rows per batch.');const aliases={company:'company_name',position:'job_title',role:'job_title',contact_email:'email',contact_phone:'phone',name:'full_name',eligibility_evidence:'eligibility_source'};const headers=rows.shift().map(v=>{const key=v.trim().toLowerCase().replace(/[ -]+/g,'_');return aliases[key]||key;});if(new Set(headers).size!==headers.length)throw Error('Duplicate column names are not allowed.');const allowed=new Set(fieldsOf('lead').map(f=>f.key).concat('full_name'));const unknown=headers.filter(v=>!allowed.has(v));if(unknown.length)throw Error('Unrecognized columns: '+unknown.join(', ')+'. Use the supplied template.');const seen=new Set(),valid=[],invalid=[];rows.forEach((row,i)=>{const raw=Object.fromEntries(headers.map((key,j)=>[key,(row[j]||'').trim()]));const v={...formDefaults('lead'),owner:'Maya Kapoor',source:'CSV import',industry:'Other',...raw};if(raw.full_name&&!raw.first_name){const parts=raw.full_name.split(/\s+/);v.first_name=parts.shift();v.last_name=parts.join(' ');}delete v.full_name;for(const f of fieldsOf('lead')){if(f.type==='number'&&v[f.key]!=='')v[f.key]=Number(v[f.key]);if(f.type==='checkbox')v[f.key]=['true','yes','1'].includes(String(v[f.key]).toLowerCase());}const errors=validateEntity('lead',v);if(row.length!==headers.length)errors.row='Column count differs from the header.';const email=v.email?.toLowerCase();if(email&&seen.has(email))errors.email='Duplicate email in this file.';if(email)seen.add(email);if(Object.keys(errors).length)invalid.push({row:i+2,name:[v.first_name,v.last_name].join(' '),errors});else valid.push(v);});pendingImport={name:file.name,valid,invalid};result=document.getElementById('import-result');if(!result)return;result.innerHTML=`<div class="notice"><strong>${h(file.name)}: ${valid.length} valid · ${invalid.length} need correction</strong><p>Matched columns: ${h(headers.join(', '))}. Existing and duplicate emails are excluded. No outreach is activated.</p></div>${invalid.length?`<div class="table-wrap"><table><thead><tr><th>CSV row</th><th>Record</th><th>Corrections</th></tr></thead><tbody>${invalid.map(r=>`<tr><td>${r.row}</td><td>${h(r.name)}</td><td>${h(Object.entries(r.errors).map(([k,v])=>k+': '+v).join(' '))}</td></tr>`).join('')}</tbody></table></div>`:''}${valid.length?`<label class="form-check-row section-gap"><input type="checkbox" id="import-persist" checked>Keep imported records on this browser</label><p class="small muted">Records are stored in this review workspace, with linked accounts and contacts.</p><button class="btn primary" data-confirm-import>Import ${valid.length} valid records</button>`:''}`;result.querySelector('[data-confirm-import]')?.addEventListener('click',commitCsvImport);}catch(error){if(result)result.innerHTML=`<div class="form-error-summary" role="alert">${h(error.message)}</div>`;}}
function commitCsvImport(){if(!pendingImport?.valid.length)return;const batch=pendingImport;const persist=!!document.getElementById('import-persist')?.checked;let count=0;for(const values of batch.valid){if(Object.keys(validateEntity('lead',values)).length)continue;activeForm={type:'lead',recordId:null,values,persist,onSaved:null};saveEntityForm();count++;}pendingImport=null;activeForm=null;navigate('leads');render();toast(count+' leads imported with linked company and contact records. '+batch.invalid.length+' rows excluded.');}

function restoreInlineRecord(){if(selectedRecord)return;const get=type=>recordsOf(type).filter(r=>r.updatedAt&&(!r._fixture||r._revision)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];const r=current==='company'?get('workspace'):current==='content-editor'?get('asset'):current==='voice'?get('script'):current==='sequence-builder'?get('sequence'):current==='playbook-builder'?get('playbook'):current==='proposal'?get('proposal'):null;if(!r)return;const map=current==='company'?{'Workspace name':'name','Product name':'product_name','Operating timezone':'timezone','Reporting currency':'currency','Default territory':'territory','Workspace owner':'owner','Approved offer summary':'offer'}:current==='content-editor'?{'Headline':'headline','Body':'body','Channel':'channel'}:current==='voice'?{'Opening':'opening','Qualification prompts':'questions'}:current==='sequence-builder'?{'Sequence name':'name'}:current==='playbook-builder'?{'Version name':'name','Trigger event':'trigger'}:{'Buyer outcome':'outcome','Scope and deliverables':'deliverables','Assumptions and commitments':'assumptions'};for(const f of inlineFields()){const key=map[f.label];if(!key||r[key]===undefined)continue;if(f.element.tagName==='SELECT'){const option=[...f.element.options].find(o=>o.value===r[key]||o.value.startsWith(r[key]+' · '));if(option)f.element.value=option.value;}else f.element.value=r[key];}}

function inlineRecord(type){return recordsOf(type).filter(r=>!r._fixture||r._revision).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0]||recordsOf(type)[0]||null;}
